function normalizeBaseUrl(baseUrl: string): string {
  const parsed = new URL(baseUrl);
  parsed.hash = '';
  parsed.search = '';
  return parsed.toString().replace(/\/$/, '');
}

function resolveEndpoint(baseUrl: string, pathname: string): string {
  return new URL(pathname, `${baseUrl}/`).toString();
}

function createApiError(
  endpoint: string,
  attempt: number,
  reason: MapApiErrorReason,
  message: string,
  status: number | null = null,
  details?: string[],
): MapApiError {
  return {
    endpoint,
    status,
    reason,
    attempt,
    message,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function isRetryableHttpStatus(status: number): boolean {
  return status === 429 || status >= 500;
}

function isAbortError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'AbortError';
  }

  return error instanceof Error && error.name === 'AbortError';
}

function createAttemptSignal(externalSignal: AbortSignal | undefined, timeoutMs: number): AttemptSignal {
  const controller = new AbortController();
  let timeoutTriggered = false;

  const onExternalAbort = () => {
    controller.abort(externalSignal?.reason);
  };

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
  }

  const timeoutHandle = setTimeout(() => {
    timeoutTriggered = true;
    controller.abort(new Error('timeout'));
  }, timeoutMs);

  const cleanup = () => {
    clearTimeout(timeoutHandle);
    if (externalSignal && !externalSignal.aborted) {
      externalSignal.removeEventListener('abort', onExternalAbort);
    }
  };

  return {
    signal: controller.signal,
    cleanup,
    didTimeout: () => timeoutTriggered,
  };
}

function createSleepWithSignal(
  sleepImpl: (ms: number) => Promise<void>,
  signal: AbortSignal | undefined,
): (ms: number) => Promise<void> {
  return async (ms: number) => {
    if (ms <= 0) {
      return;
    }

    if (!signal) {
      await sleepImpl(ms);
      return;
    }

    if (signal.aborted) {
      throw new DOMException('Aborted', 'AbortError');
    }

    await new Promise<void>((resolve, reject) => {
      const timeoutHandle = setTimeout(() => {
        signal.removeEventListener('abort', onAbort);
        resolve();
      }, ms);

      const onAbort = () => {
        clearTimeout(timeoutHandle);
        reject(new DOMException('Aborted', 'AbortError'));
      };

      signal.addEventListener('abort', onAbort, { once: true });
    });
  };
}

export interface MapApiClient {
  fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>>;
  fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>>;
  fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>>;
  resolveMapUrl(): string;
  resolveFloorPlanImageUrl(target: FloorPlanTarget): string;
  resolveCampusImageUrl(): string;
}

export function createMapApiClient(config: MapApiClientConfig): MapApiClient {
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const fetchImpl: Fetcher =
    config.fetchImpl ?? ((input, init) => fetch(input, init));
  const retryPolicy: MapApiRetryPolicy = {
    ...DEFAULT_RETRY_POLICY,
    ...config.retryPolicy,
  };
  const sleepImpl = config.sleep ?? ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)));

  async function executeGet(
    endpoint: string,
    options: MapApiRequestOptions | undefined,
  ): Promise<HttpSuccess | HttpFailure> {
    const maxAttempts = options?.maxAttempts ?? retryPolicy.maxAttempts;
    const timeoutMs = options?.timeoutMs ?? retryPolicy.timeoutMs;
    const sleepWithSignal = createSleepWithSignal(sleepImpl, options?.signal);

    let lastError: MapApiError | null = null;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      const attemptSignal = createAttemptSignal(options?.signal, timeoutMs);

      try {
        const response = await fetchImpl(endpoint, {
          method: 'GET',
          signal: attemptSignal.signal as unknown as RequestInit['signal'],
        });

        if (!response.ok) {
          const error = createApiError(
            endpoint,
            attempt,
            'http-error',
            `Request failed with HTTP ${response.status}.`,
            response.status,
          );

          if (attempt < maxAttempts && isRetryableHttpStatus(response.status)) {
            lastError = error;
            const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
            await sleepWithSignal(delay);
            continue;
          }

          return { ok: false, error };
        }

        return {
          ok: true,
          endpoint,
          attempt,
          response,
        };
      } catch (error) {
        const reason: MapApiErrorReason = attemptSignal.didTimeout()
          ? 'timeout'
          : options?.signal?.aborted || isAbortError(error)
            ? 'aborted'
            : 'network-error';

        const apiError = createApiError(
          endpoint,
          attempt,
          reason,
          reason === 'timeout'
            ? `Request timed out after ${timeoutMs}ms.`
            : reason === 'aborted'
              ? 'Request was aborted.'
              : error instanceof Error
                ? error.message
                : 'Network request failed.',
        );

        const shouldRetry = reason !== 'aborted' && attempt < maxAttempts;
        if (shouldRetry) {
          lastError = apiError;
          const delay = retryPolicy.baseDelayMs * 2 ** (attempt - 1);
          await sleepWithSignal(delay);
          continue;
        }

        return { ok: false, error: apiError };
      } finally {
        attemptSignal.cleanup();
      }
    }

    return {
      ok: false,
      error:
        lastError ??
        createApiError(endpoint, maxAttempts, 'network-error', 'Request failed after retries.'),
    };
  }

  async function fetchMapGraph(options?: MapApiRequestOptions): Promise<MapApiResult<NavGraph>> {
    const endpoint = resolveMapEndpoint(baseUrl);
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    let payload: unknown;

    try {
      payload = await responseResult.response.json();
    } catch (error) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'invalid-json',
          error instanceof Error ? error.message : 'Response body is not valid JSON.',
          responseResult.response.status,
        ),
      };
    }

    const validated = validateNavGraphPayload(payload);
    if (!validated.ok) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'contract-validation-error',
          validated.error.message,
          responseResult.response.status,
          validated.error.issues,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: validated.data,
    };
  }

  async function fetchImageContract(
    endpoint: string,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    const responseResult = await executeGet(endpoint, options);

    if (!responseResult.ok) {
      return responseResult;
    }

    const contentType = responseResult.response.headers.get('content-type');
    if (!contentType || !contentType.toLowerCase().startsWith('image/')) {
      return {
        ok: false,
        error: createApiError(
          endpoint,
          responseResult.attempt,
          'unexpected-content-type',
          `Expected image content-type but received "${contentType ?? 'missing'}".`,
          responseResult.response.status,
        ),
      };
    }

    return {
      ok: true,
      endpoint,
      status: responseResult.response.status,
      attempt: responseResult.attempt,
      data: {
        endpoint,
        contentType,
        cacheControl: responseResult.response.headers.get('cache-control'),
      },
    };
  }

  function resolveMapUrl(): string {
    return resolveMapEndpoint(baseUrl);
  }

  function resolveFloorPlanImageUrl(target: FloorPlanTarget): string {
    return resolveFloorPlanImageEndpoint(baseUrl, target);
  }

  function resolveCampusImageUrl(): string {
    return resolveCampusImageEndpoint(baseUrl);
  }

  async function fetchFloorPlanImageContract(
    target: FloorPlanTarget,
    options?: MapApiRequestOptions,
  ): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveFloorPlanImageUrl(target), options);
  }

  async function fetchCampusImageContract(options?: MapApiRequestOptions): Promise<MapApiResult<MapImageContract>> {
    return fetchImageContract(resolveCampusImageUrl(), options);
  }

  return {
    fetchMapGraph,
    fetchFloorPlanImageContract,
    fetchCampusImageContract,
    resolveMapUrl,
    resolveFloorPlanImageUrl,
    resolveCampusImageUrl,
  };
}

export function resolveMapEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/map');
}

export function resolveFloorPlanImageEndpoint(baseUrl: string, target: FloorPlanTarget): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const buildingId = Number(target.buildingId);
  const floorNumber = Number(target.floorNumber);
  return resolveEndpoint(normalizedBaseUrl, `/api/floor-plan/${buildingId}/${floorNumber}`);
}

export function resolveCampusImageEndpoint(baseUrl: string): string {
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  return resolveEndpoint(normalizedBaseUrl, '/api/campus/image');
}

export interface ViewportPoint {
  x: number;
  y: number;
}

export interface ViewportDimensions {
  width: number;
  height: number;
}

export interface MapTransform {
  scale: number;
  rotationDeg: number;
  translation: ViewportPoint;
}

export interface PinchRotateInput {
  scaleFactor: number;
  rotationDeltaDeg: number;
  focal: ViewportPoint;
  viewport: ViewportDimensions | null | undefined;
}

export const MIN_VIEWPORT_SCALE = 0.5;
export const MAX_VIEWPORT_SCALE = 4;

const DEFAULT_TRANSFORM: MapTransform = {
  scale: 1,
  rotationDeg: 0,
  translation: { x: 0, y: 0 },
};

const EPSILON = 1e-6;

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}

function rotatePoint(point: ViewportPoint, angleRad: number): ViewportPoint {
  const cos = Math.cos(angleRad);
  const sin = Math.sin(angleRad);

  return {
    x: point.x * cos - point.y * sin,
    y: point.x * sin + point.y * cos,
  };
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

function isValidViewport(viewport: ViewportDimensions | null | undefined): viewport is ViewportDimensions {
  return (
    !!viewport &&
    isFiniteNumber(viewport.width) &&
    isFiniteNumber(viewport.height) &&
    viewport.width > 0 &&
    viewport.height > 0
  );
}

function clampFocalPoint(focal: ViewportPoint, viewport: ViewportDimensions): ViewportPoint {
  if (!isFiniteNumber(focal.x) || !isFiniteNumber(focal.y)) {
    return {
      x: viewport.width / 2,
      y: viewport.height / 2,
    };
  }

  return {
    x: clamp(focal.x, 0, viewport.width),
    y: clamp(focal.y, 0, viewport.height),
  };
}

export function createInitialMapTransform(): MapTransform {
  return {
    scale: DEFAULT_TRANSFORM.scale,
    rotationDeg: DEFAULT_TRANSFORM.rotationDeg,
    translation: { ...DEFAULT_TRANSFORM.translation },
  };
}

export function clampViewportScale(scale: number): number {
  if (!isFiniteNumber(scale)) {
    return DEFAULT_TRANSFORM.scale;
  }

  return clamp(scale, MIN_VIEWPORT_SCALE, MAX_VIEWPORT_SCALE);
}

export function normalizeRotationDeg(rotationDeg: number): number {
  if (!isFiniteNumber(rotationDeg)) {
    return DEFAULT_TRANSFORM.rotationDeg;
  }

  return ((((rotationDeg + 180) % 360) + 360) % 360) - 180;
}

export function worldFromScreen(screenPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const translated = {
    x: screenPoint.x - transform.translation.x,
    y: screenPoint.y - transform.translation.y,
  };

  const unrotated = rotatePoint(translated, -toRadians(normalizedRotation));

  return {
    x: unrotated.x / scale,
    y: unrotated.y / scale,
  };
}

export function screenFromWorld(worldPoint: ViewportPoint, transform: MapTransform): ViewportPoint {
  const scale = clampViewportScale(transform.scale);
  const normalizedRotation = normalizeRotationDeg(transform.rotationDeg);

  const scaled = {
    x: worldPoint.x * scale,
    y: worldPoint.y * scale,
  };

  const rotated = rotatePoint(scaled, toRadians(normalizedRotation));

  return {
    x: rotated.x + transform.translation.x,
    y: rotated.y + transform.translation.y,
  };
}

export function applyPanDelta(transform: MapTransform, delta: ViewportPoint): MapTransform {
  if (!isFiniteNumber(delta.x) || !isFiniteNumber(delta.y)) {
    return transform;
  }

  const nextTranslation = {
    x: transform.translation.x + delta.x,
    y: transform.translation.y + delta.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    ...transform,
    translation: nextTranslation,
  };
}

export function applyPinchRotate(transform: MapTransform, input: PinchRotateInput): MapTransform {
  if (!isValidViewport(input.viewport)) {
    return transform;
  }

  if (
    !isFiniteNumber(input.scaleFactor) ||
    !isFiniteNumber(input.rotationDeltaDeg) ||
    input.scaleFactor <= 0
  ) {
    return transform;
  }

  const focalPoint = clampFocalPoint(input.focal, input.viewport);
  const worldAnchor = worldFromScreen(focalPoint, transform);

  const nextScale = clampViewportScale(transform.scale * input.scaleFactor);
  const nextRotation = normalizeRotationDeg(transform.rotationDeg + input.rotationDeltaDeg);

  const projectedAnchor = screenFromWorld(worldAnchor, {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: { x: 0, y: 0 },
  });

  const nextTranslation = {
    x: focalPoint.x - projectedAnchor.x,
    y: focalPoint.y - projectedAnchor.y,
  };

  if (!isFiniteNumber(nextTranslation.x) || !isFiniteNumber(nextTranslation.y)) {
    return transform;
  }

  return {
    scale: nextScale,
    rotationDeg: nextRotation,
    translation: nextTranslation,
  };
}

export function mapTransformsEqual(a: MapTransform, b: MapTransform): boolean {
  return (
    Math.abs(a.scale - b.scale) < EPSILON &&
    Math.abs(a.rotationDeg - b.rotationDeg) < EPSILON &&
    Math.abs(a.translation.x - b.translation.x) < EPSILON &&
    Math.abs(a.translation.y - b.translation.y) < EPSILON
  );
}

/**
 * DestinationPicker — building/floor/node accordion with fuzzy text search.
 * Pressing a node calls onNodeSelect. "Set Start" / "Set Destination" toggle
 * in header reflects the activeField from RouteSelection.
 */

import { useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';

import { useLocationSearch } from '../../hooks/useLocationSearch';
import type { NormalizedNavGraph } from '../../domain/navGraph';
import type { NavNode } from '../../../src/shared/types';
import type { RouteSelection } from '../../hooks/useRouteSelection';

const DEBOUNCE_MS = 300;

interface Props {
  graph: NormalizedNavGraph;
  selection: RouteSelection;
  onNodeSelect: (node: NavNode) => void;
}

const TYPE_BADGE: Record<string, string> = {
  room: '📍',
  entrance: '🚪',
  elevator: '🛗',
  restroom: '🚻',
  landmark: '⭐',
  stairs: '⬆️',
  ramp: '♿',
  junction: '⬡',
  hallway: '─',
};

const ACCESSIBLE_ICON = '♿';

export function DestinationPicker({ graph, selection, onNodeSelect }: Props) {
  const [query, setQuery] = useState('');
  const [debouncedQuery, setDebouncedQuery] = useState('');

  // Debounce search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedQuery(query);
    }, DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [query]);

  const { buildings, totalMatches } = useLocationSearch(graph, debouncedQuery);

  const activeLabel = selection.activeField === 'start' ? 'Set Start' : 'Set Destination';
  const otherLabel = selection.activeField === 'start' ? 'Set Destination' : 'Set Start';

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerLabel}>{activeLabel}</Text>
        <Text style={styles.resultCount}>
          {totalMatches} {totalMatches === 1 ? 'result' : 'results'}
        </Text>
      </View>

      {/* Search input */}
      <TextInput
        style={styles.searchInput}
        placeholder="Search location..."
        placeholderTextColor="#64748b"
        value={query}
        onChangeText={setQuery}
        autoCapitalize="none"
        autoCorrect={false}
      />

      {/* Active field indicator */}
      <View style={styles.fieldToggle}>
        <Text style={styles.fieldText}>Picking: </Text>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'start' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('start')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'start' && styles.fieldChipTextActive]}>
            Start {selection.start ? `(${selection.start.label})` : ''}
          </Text>
        </Pressable>
        <Pressable
          style={[styles.fieldChip, selection.activeField === 'destination' && styles.fieldChipActive]}
          onPress={() => selection.setActiveField('destination')}
        >
          <Text style={[styles.fieldChipText, selection.activeField === 'destination' && styles.fieldChipTextActive]}>
            Dest {selection.destination ? `(${selection.destination.label})` : ''}
          </Text>
        </Pressable>
        {(selection.start || selection.destination) && (
          <Pressable style={styles.swapButton} onPress={selection.swap}>
            <Text style={styles.swapButtonText}>⇄ Swap</Text>
          </Pressable>
        )}
      </View>

      {/* Results */}
      <FlatList
        data={buildings}
        keyExtractor={item => String(item.buildingId)}
        style={styles.list}
        renderItem={({ item: building }) => (
          <BuildingAccordion
            building={building}
            onNodeSelect={onNodeSelect}
          />
        )}
        ListEmptyComponent={
          <Text style={styles.emptyText}>
            {debouncedQuery ? 'No locations match your search.' : 'No locations available.'}
          </Text>
        }
      />
    </View>
  );
}

