function makeSelection() {
  return {
    start: null as ReturnType<typeof vi.fn> extends ((...args: never[]) => infer R) ? R : never,
    destination: null,
    activeField: 'start' as const,
    bothSelected: false,
    setStart: vi.fn(),
    setDestination: vi.fn(),
    setActiveField: vi.fn(),
    setFromTap: vi.fn(),
    swap: vi.fn(),
    clearStart: vi.fn(),
    clearDestination: vi.fn(),
