/**
 * RoutePreview — step-by-step directions grouped by floor.
 *
 * Props:
 * - directions: DirectionsResult from the route session
 * - floorMap: Map<floorId, NavFloor> from the normalized graph
 * - accessibleMode: boolean to highlight accessible path elements
 * - onFloorChange: callback to switch the active floor
 */

import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';

import { groupDirectionSections } from '../../routing/directionSections';
import type { DirectionsResult, DirectionSection, DirectionStep } from '../../domain/navGraph';
import type { NavFloor } from '../../../src/shared/types';

/* ─── Icons ─── */

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

/* ─── Step icon color ─── */

function iconColor(step: DirectionStep, accessibleMode: boolean): string {
  if (step.isAccessibleSegment) return '#facc15'; // amber for accessible segments
  if (step.icon === 'arrive') return '#4ade80'; // green for arrival
  if (accessibleMode && (step.icon === 'elevator' || step.icon === 'ramp')) return '#facc15';
  return '#38bdf8'; // cyan for standard
}

/* ─── Duration formatting ─── */

function formatDuration(sec: number): string {
  if (sec < 60) return `${sec}s`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return s > 0 ? `${m}m ${s}s` : `${m}m`;
}

/* ─── Distance formatting (normalized → approximate meters) ─── */

function formatDistance(norm: number): string {
  // Normalized coordinate space → approximate real distance
  // Assume campus coordinate space roughly maps to 50m per unit
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/* ─── Props ─── */

interface Props {
  directions: DirectionsResult;
  accessibleMode: boolean;
}

/* ─── Component ─── */

export function RoutePreview({ directions, accessibleMode }: Props) {
  const sections = groupDirectionSections(directions.steps);

  return (
    <View style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Route Preview</Text>
        <View style={styles.summaryRow}>
          <Text style={styles.summaryText}>
            {formatDistance(directions.totalDistanceNorm)}
          </Text>
          <Text style={styles.summaryDivider}>·</Text>
          <Text style={styles.summaryText}>
            {formatDuration(directions.totalDurationSec)}
          </Text>
          <Text style={styles.summaryDivider}>·</Text>
          <Text style={styles.stepCount}>{directions.steps.length} steps</Text>
        </View>
      </View>

      {/* Sections */}
      <FlatList
        data={sections}
        keyExtractor={item => String(item.floorId)}
        style={styles.sectionList}
        renderItem={({ item: section }) => (
          <FloorSectionView section={section} accessibleMode={accessibleMode} />
        )}
        ItemSeparatorComponent={() => <View style={styles.sectionSeparator} />}
        ListEmptyComponent={
          <Text style={styles.emptyText}>No directions available.</Text>
        }
      />
    </View>
  );
}

/* ─── Floor section view ─── */

interface FloorSectionProps {
  section: DirectionSection;
  accessibleMode: boolean;
}

function FloorSectionView({ section, accessibleMode }: FloorSectionProps) {
  return (
    <View style={styles.floorSection}>
      <Text style={styles.floorHeader}>
        Floor {section.floorNumber}
      </Text>
      {section.steps.map((step, idx) => (
        <StepRow key={idx} step={step} accessibleMode={accessibleMode} />
      ))}
    </View>
  );
}

/* ─── Individual step row ─── */

interface StepRowProps {
  step: DirectionStep;
  accessibleMode: boolean;
}

function StepRow({ step, accessibleMode }: StepRowProps) {
  const icon = stepIcon(step);
  const color = iconColor(step, accessibleMode);
  const isAccessible = step.isAccessibleSegment || step.icon === 'elevator' || step.icon === 'ramp';

  return (
    <View style={[styles.stepRow, isAccessible && accessibleMode && styles.stepRowAccessible]}>
      <View style={[styles.stepIconContainer, { backgroundColor: color + '20' }]}>
        <Text style={[styles.stepIcon, { color }]}>{icon}</Text>
      </View>
      <View style={styles.stepContent}>
        <Text style={styles.instruction} numberOfLines={2}>
          {step.instruction}
        </Text>
        <View style={styles.stepMeta}>
          <Text style={styles.stepMetaText}>{formatDistance(step.distanceM)}</Text>
          <Text style={styles.stepMetaDivider}>·</Text>
          <Text style={styles.stepMetaText}>{formatDuration(step.durationSec)}</Text>
        </View>
      </View>
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#020617',
  },
  header: {
    paddingHorizontal: 16,
    paddingTop: 12,
    paddingBottom: 8,
    borderBottomWidth: 1,
    borderBottomColor: '#1e293b',
    gap: 4,
  },
  headerTitle: {
    color: '#f8fafc',
    fontSize: 16,
    fontWeight: '700',
  },
  summaryRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  summaryText: {
    color: '#38bdf8',
    fontSize: 13,
    fontWeight: '600',
  },
  summaryDivider: {
    color: '#475569',
    fontSize: 13,
  },
  stepCount: {
    color: '#64748b',
    fontSize: 12,
  },
  sectionList: {
    flex: 1,
  },
  sectionSeparator: {
    height: 8,
    backgroundColor: '#0a0f1e',
  },
  floorSection: {
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  floorHeader: {
    color: '#475569',
    fontSize: 11,
    fontWeight: '600',
    letterSpacing: 1,
    textTransform: 'uppercase',
    marginBottom: 8,
  },
  stepRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    gap: 10,
    paddingVertical: 8,
    paddingHorizontal: 4,
  },
  stepRowAccessible: {
    backgroundColor: '#1c1408',
    borderRadius: 8,
    paddingHorizontal: 8,
  },
  stepIconContainer: {
    width: 32,
    height: 32,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
  },
  stepIcon: {
    fontSize: 16,
    fontWeight: '700',
  },
  stepContent: {
    flex: 1,
    gap: 2,
  },
  instruction: {
    color: '#e2e8f0',
    fontSize: 14,
    lineHeight: 18,
  },
  stepMeta: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  stepMetaText: {
    color: '#64748b',
    fontSize: 12,
  },
  stepMetaDivider: {
    color: '#334155',
    fontSize: 12,
  },
  emptyText: {
    color: '#475569',
    fontSize: 14,
    textAlign: 'center',
    marginTop: 20,
  },
});

/**
 * RoutePathOverlay — renders the computed route path on top of the floor plan image.
 *
 * Props:
 * - path: Array<{x: number; y: number; floorId: number}> — route waypoints from the session
 * - activeFloorId: number — currently visible floor to filter path nodes
 * - viewport: ViewportDimensions — current viewport size for coordinate mapping
 * - scale: number — current map scale from MapTransform
 *
 * Strategy: View-based polyline (no new SVG dependency). For each adjacent pair of
 * nodes on the active floor, render:
 *   - Two endpoint dots (width/height 8, borderRadius 4)
 *   - A connecting line rotated to match the bearing
 */

import { StyleSheet, View } from 'react-native';
import type { ViewportDimensions } from '../../map/mapTransform';

/* ─── Types ─── */

export interface RoutePathPoint {
  x: number;       // normalized [0,1]
  y: number;       // normalized [0,1]
  floorId: number;
}

interface Props {
  path: RoutePathPoint[];
  activeFloorId: number;
  viewport: ViewportDimensions;
  scale: number;
}

/* ─── Helpers ─── */

function bearing(from: RoutePathPoint, to: RoutePathPoint): number {
  const dx = (to.x - from.x) * scale * viewport.width;
  const dy = (to.y - from.y) * scale * viewport.height;
  return Math.atan2(dy, dx) * (180 / Math.PI);
}

function segmentLength(a: RoutePathPoint, b: RoutePathPoint): number {
  const dx = (b.x - a.x) * viewport.width * scale;
  const dy = (b.y - a.y) * viewport.height * scale;
  return Math.hypot(dx, dy);
}

let viewport: ViewportDimensions;
let currentScale: number;

/* ─── Component ─── */

export function RoutePathOverlay({ path, activeFloorId, viewport: vp, scale }: Props) {
  viewport = vp;
  currentScale = scale;

  // Filter to nodes on the active floor
  const floorNodes = path.filter(n => n.floorId === activeFloorId);

  if (floorNodes.length < 2) {
    // Draw single node dot
    if (floorNodes.length === 1) {
      const node = floorNodes[0];
      return (
        <RouteDot node={node} scale={scale} viewport={vp} isStart />
      );
    }
    return null;
  }

  return (
    <View style={styles.overlay} pointerEvents="none">
      {floorNodes.map((node, i) => {
        const isStart = i === 0;
        const isEnd = i === floorNodes.length - 1;
        return (
          <RouteSegment
            key={`seg-${i}`}
            from={node}
            to={floorNodes[i + 1] ?? node}
            isStart={isStart}
            isEnd={isEnd}
          />
        );
      })}
    </View>
  );
}

/* ─── Individual dot ─── */

interface RouteDotProps {
  node: RoutePathPoint;
  scale: number;
  viewport: ViewportDimensions;
  isStart?: boolean;
  isEnd?: boolean;
}

function RouteDot({ node, scale, viewport: vp }: RouteDotProps) {
  const left = node.x * vp.width * scale - 4;
  const top = node.y * vp.height * scale - 4;

  return (
    <View
      style={[
        styles.dot,
        {
          left,
          top,
        },
      ]}
    />
  );
}

/* ─── Segment: dot + connecting line ─── */

interface RouteSegmentProps {
  from: RoutePathPoint;
  to: RoutePathPoint;
  isStart: boolean;
  isEnd: boolean;
}

function RouteSegment({ from, to, isStart, isEnd }: RouteSegmentProps) {
  const len = segmentLength(from, to);
  const angleDeg = bearing(from, to);

  // Dot positions
  const startLeft = from.x * viewport.width * viewport.scale - 4;
  const startTop = from.y * viewport.height * viewport.scale - 4;
  const endLeft = to.x * viewport.width * viewport.scale - 4;
  const endTop = to.y * viewport.height * viewport.scale - 4;

  return (
    <View style={styles.overlay} pointerEvents="none">
      {/* Start dot */}
      <View style={[styles.dot, styles.dotStart, { left: startLeft, top: startTop }]} />
      {/* End dot */}
      <View style={[styles.dot, styles.dotEnd, { left: endLeft, top: endTop }]} />
      {/* Connecting line (positioned at midpoint, rotated) */}
      {len > 0 && (
        <View
          style={[
            styles.line,
            {
              width: len,
              left: startLeft + 4,
              top: startTop + 3,
              transform: [{ rotate: `${angleDeg}deg` }],
            },
          ]}
        />
      )}
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
  },
  dot: {
    position: 'absolute',
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: '#38bdf8',
  },
  dotStart: {
    backgroundColor: '#4ade80', // green for start
  },
  dotEnd: {
    backgroundColor: '#f87171', // red for destination
  },
  line: {
    position: 'absolute',
    height: 2,
    backgroundColor: '#38bdf8',
    transformOrigin: 'left center',
  },
});

/**
 * MapViewportFloor — floor-switching extension of MapViewport.
 *
 * Composes:
 * - MapViewport (floor plan image with pan/pinch/rotate controls)
 * - Floor selector strip (horizontal ScrollView of floor buttons)
 * - RoutePathOverlay (polyline overlay on active floor)
 *
 * The active floor target is tracked in state and drives both
 * which image is shown and which floor segment is rendered.
 */

import { useCallback, useEffect, useState } from 'react';
import {
  FlatList,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { MapViewport } from './MapViewport';
import { RoutePathOverlay, type RoutePathPoint } from '../route/RoutePathOverlay';
import type { FloorPlanTarget } from '../../data/mapApiClient';
import type { MapTransform } from './mapTransform';
import type { ViewportDimensions } from './mapTransform';

/* ─── Props ─── */

export interface MapViewportFloorProps {
  /** MapViewport props */
  onTransformChange?: (transform: MapTransform) => void;
  /** All available floor targets for the active route */
  floorTargets: FloorPlanTarget[];
  /** Currently selected floor target */
  activeFloorTarget: FloorPlanTarget | null;
  /** Route path waypoints (normalized coordinates) */
  routePath: RoutePathPoint[];
  /** Called when user presses a floor button */
  onFloorChange: (target: FloorPlanTarget) => void;
  /** Whether to show the route path overlay */
  showRouteOverlay?: boolean;
  /** Whether to show the floor selector strip */
  showFloorSelector?: boolean;
}

/* ─── State ─── */

interface FloorButtonData {
  target: FloorPlanTarget;
  label: string;
  isActive: boolean;
}

/* ─── Component ─── */

export function MapViewportFloor({
  onTransformChange,
  floorTargets,
  activeFloorTarget,
  routePath,
  onFloorChange,
  showRouteOverlay = true,
  showFloorSelector = true,
}: MapViewportFloorProps) {
  const [transform, setTransform] = useState<MapTransform>({
    scale: 1,
    rotationDeg: 0,
    translation: { x: 0, y: 0 },
  });
  const [viewportDimensions, setViewportDimensions] = useState<ViewportDimensions>({ width: 300, height: 300 });

  const handleTransformChange = useCallback(
    (t: MapTransform) => {
      setTransform(t);
      onTransformChange?.(t);
    },
    [onTransformChange],
  );

  // Build floor button data
  const floorButtons: FloorButtonData[] = floorTargets.map(target => ({
    target,
    label: `Bldg ${target.buildingId} Fl ${target.floorNumber}`,
    isActive: activeFloorTarget !== null
      && activeFloorTarget.buildingId === target.buildingId
      && activeFloorTarget.floorNumber === target.floorNumber,
  }));

  return (
    <View style={styles.container}>
      {/* Map viewport with optional route overlay */}
      <View style={styles.mapContainer}>
        <MapViewport
          imageUri=""
          onTransformChange={handleTransformChange}
        />
        {showRouteOverlay && activeFloorTarget && (
          <RoutePathOverlay
            path={routePath}
            activeFloorId={activeFloorTarget.floorId ?? 0}
            viewport={viewportDimensions}
            scale={transform.scale}
          />
        )}
      </View>

      {/* Floor selector strip */}
      {showFloorSelector && floorButtons.length > 0 && (
        <View style={styles.floorSelector}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.floorScrollContent}
          >
            {floorButtons.map((btn, idx) => (
              <Pressable
                key={`floor-${idx}`}
                style={[styles.floorButton, btn.isActive && styles.floorButtonActive]}
                onPress={() => onFloorChange(btn.target)}
              >
                <Text style={[styles.floorButtonText, btn.isActive && styles.floorButtonTextActive]}>
                  {btn.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    width: '100%',
    gap: 8,
  },
  mapContainer: {
    flex: 1,
    minHeight: 280,
    borderRadius: 12,
    overflow: 'hidden',
  },
  floorSelector: {
    paddingVertical: 4,
  },
  floorScrollContent: {
    flexDirection: 'row',
    gap: 8,
    paddingHorizontal: 4,
    paddingVertical: 4,
  },
  floorButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 12,
    paddingVertical: 6,
  },
  floorButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  floorButtonText: {
    color: '#94a3b8',
    fontSize: 12,
    fontWeight: '500',
  },
  floorButtonTextActive: {
    color: '#38bdf8',
    fontWeight: '700',
  },
});

/**
 * App — visitor navigation runtime (no sign-in required).
 *
 * Composition:
 * - Bootstrap: loads nav graph + campus image from configured endpoints
 * - DestinationPicker: building/floor/node search with start/destination selection
 * - MapViewportFloor: floor plan image viewer + route path overlay + floor switcher
 * - RoutePreview: step-by-step directions when route is ready
 * - Accessible mode toggle: switches between standard / accessible routing
 */

import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {
  IDLE_MAP_BOOTSTRAP_STATE,
  type MapBootstrapState,
  runMapBootstrap,
} from './bootstrap/mapBootstrapState';
import { normalizeNavGraph } from './domain/navGraph';
import type { NormalizedNavGraph } from './domain/navGraph';
import { MapViewport } from './map/MapViewport';
import { MapViewportFloor } from './map/MapViewportFloor';
import type { FloorPlanTarget } from './data/mapApiClient';
import { createMapApiClient } from './data/mapApiClient';
import {
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
} from './map/mapTransform';
import { DestinationPicker } from './components/destination/DestinationPicker';
import { RoutePreview } from './components/route/RoutePreview';
import { RoutePathOverlay, type RoutePathPoint } from './components/route/RoutePathOverlay';
import { useRouteSelection } from './hooks/useRouteSelection';
import { useRouteSession } from './routing/useRouteSession';
import type { NavNode } from '../src/shared/types';

/* ─── Helpers ─── */

function nextAttemptFromState(state: MapBootstrapState): number {
  if (state.phase === 'idle') return 1;
  return state.attempt + 1;
}

function phaseMessage(state: MapBootstrapState): string {
  switch (state.phase) {
    case 'idle':    return 'Preparing startup checks.';
    case 'loading': return `Loading ${state.currentPhase} contract from ${state.endpoint}.`;
    case 'ready':   return 'CampusNav map is ready for visitor navigation.';
    case 'error':   return state.message;
  }
}

function formatMetric(value: number): string {
  return Number.isFinite(value) ? value.toFixed(2) : '0';
}

/* ─── Floor target from normalized graph ─── */

function buildFloorTargets(graph: NormalizedNavGraph): FloorPlanTarget[] {
  const targets: FloorPlanTarget[] = [];
  for (const building of graph.graph.buildings) {
    for (const floor of building.floors) {
      targets.push({ buildingId: building.id, floorNumber: floor.floorNumber });
    }
  }
  return targets;
}

/* ─── Route path from session ready state ─── */

function buildRoutePath(sessionPhase: 'ready', graph: NormalizedNavGraph): RoutePathPoint[] {
  // The path result from MobilePathfindingEngine contains nodeIds
  // We map each to normalized coordinates from the graph
  if (!sessionPhase || sessionPhase !== 'ready') return [];
  return [];
}

/* ─── Component ─── */

export default function App() {
  const [bootstrapState, setBootstrapState] = useState<MapBootstrapState>(IDLE_MAP_BOOTSTRAP_STATE);
  const [transformState, setTransformState] = useState<MapTransform>(createInitialMapTransform());
  const [graph, setGraph] = useState<NormalizedNavGraph | null>(null);
  const [imageUri, setImageUri] = useState<string>('');
  const [activeFloorTarget, setActiveFloorTarget] = useState<FloorPlanTarget | null>(null);
  const [routePath, setRoutePath] = useState<RoutePathPoint[]>([]);
  const [accessibleMode, setAccessibleMode] = useState(false);
  const [floorTargets, setFloorTargets] = useState<FloorPlanTarget[]>([]);

  /* ─── Bootstrap ─── */

  const executeBootstrap = useCallback(async (attempt: number) => {
    const result = await runMapBootstrap({ attempt });
    for (const t of result.transitions) {
      if (t.phase === 'loading') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, currentPhase: t.currentPhase, endpoint: t.endpoint });
      if (t.phase === 'ready') console.info('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, endpoint: t.image.endpoint });
      if (t.phase === 'error') console.warn('[mobile-bootstrap]', { phase: t.phase, attempt: t.attempt, failedPhase: t.failedPhase, reason: t.reason, recoverable: t.recoverable });
    }
    setBootstrapState(result.state);
  }, []);

  useEffect(() => {
    void executeBootstrap(1);
  }, [executeBootstrap]);

  /* ─── Normalize graph once ready ─── */

  useEffect(() => {
    if (bootstrapState.phase !== 'ready') return;
    const result = normalizeNavGraph(bootstrapState.graph);
    if (!result.ok) {
      setBootstrapState({
        phase: 'error',
        attempt: bootstrapState.attempt,
        failedPhase: 'graph-normalization',
        reason: result.error.message,
        endpoint: bootstrapState.apiBaseUrl,
        recoverable: false,
      });
      return;
    }
    const normalized = result.data;
    setGraph(normalized);
    const targets = buildFloorTargets(normalized);
    setFloorTargets(targets);
    if (targets.length > 0) setActiveFloorTarget(targets[0]);
  }, [bootstrapState]);

  /* ─── Map API client for floor images ─── */

  const mapClient = graph && bootstrapState.phase === 'ready'
    ? createMapApiClient({ baseUrl: bootstrapState.apiBaseUrl })
    : null;

  /* ─── Update floor image when activeFloorTarget changes ─── */

  useEffect(() => {
    if (!mapClient || !activeFloorTarget) { setImageUri(''); return; }
    const url = mapClient.resolveFloorPlanImageUrl(activeFloorTarget);
    setImageUri(url);
  }, [mapClient, activeFloorTarget]);

  /* ─── Route selection ─── */

  const selection = useRouteSelection();

  /* ─── Route session ─── */

  const { sessionState, routeMode, setRouteMode } = graph
    ? useRouteSession({ graph, selection })
    : { sessionState: null, routeMode: 'standard' as const, setRouteMode: () => {} };

  /* ─── Update route mode when accessibleMode changes ─── */

  useEffect(() => {
    setRouteMode(accessibleMode ? 'accessible' : 'standard');
  }, [accessibleMode, setRouteMode]);

  /* ─── Build route path when session is ready ─── */

  useEffect(() => {
    if (!sessionState || sessionState.phase !== 'ready' || !graph) {
      setRoutePath([]);
      return;
    }
    const { path } = sessionState;
    const waypoints: RoutePathPoint[] = [];
    for (const nodeId of path.nodeIds) {
      const record = graph.nodeById.get(nodeId);
      if (!record) continue;
      const node = record.node;
      waypoints.push({ x: node.x, y: node.y, floorId: record.floorId });
    }
    setRoutePath(waypoints);
  }, [sessionState, graph]);

  /* ─── Transform change handler ─── */

  const onTransformChange = useCallback((nextTransform: MapTransform) => {
    setTransformState(current =>
      mapTransformsEqual(current, nextTransform)
        ? current
        : { scale: nextTransform.scale, rotationDeg: nextTransform.rotationDeg, translation: { ...nextTransform.translation } },
    );
  }, []);

  /* ─── Node select handler ─── */

  const onNodeSelect = useCallback((node: NavNode) => {
    selection.setFromTap(node);
    // After selection, set the active floor to the node's floor
    if (graph) {
      const record = graph.nodeById.get(node.id);
      if (record) {
        const target = floorTargets.find(t => t.buildingId === record.buildingId && t.floorNumber === record.floorNumber);
        if (target) setActiveFloorTarget(target);
      }
    }
  }, [selection, graph, floorTargets]);

  /* ─── Accessible mode toggle ─── */

  const toggleAccessibleMode = useCallback(() => {
    setAccessibleMode(prev => !prev);
  }, []);

  /* ─── Retry handler ─── */

  const onRetryPress = useCallback(() => {
    void executeBootstrap(nextAttemptFromState(bootstrapState));
  }, [executeBootstrap, bootstrapState]);

  /* ─── Phase: idle / loading ─── */

  if (bootstrapState.phase === 'idle' || bootstrapState.phase === 'loading') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.subtitle}>Visitor runtime shell (no sign-in)</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: {bootstrapState.phase}</Text>
        <Text style={styles.statusMessage}>{phaseMessage(bootstrapState)}</Text>
        {bootstrapState.phase === 'loading' && (
          <View style={styles.loadingRow}>
            <ActivityIndicator size="small" color="#38bdf8" />
            <Text style={styles.loadingText}>{bootstrapState.currentPhase}</Text>
          </View>
        )}
      </View>
    );
  }

  /* ─── Phase: error ─── */

  if (bootstrapState.phase === 'error') {
    return (
      <View style={styles.container}>
        <Text style={styles.title}>CampusNav</Text>
        <Text style={styles.statusLabel}>Bootstrap phase: error</Text>
        <Text style={styles.errorReason}>Failed phase: {bootstrapState.failedPhase}</Text>
        <Text style={styles.errorReason}>Reason: {bootstrapState.reason}</Text>
        <Text style={styles.errorReason}>Endpoint: {bootstrapState.endpoint ?? 'n/a'}</Text>
        <Pressable onPress={onRetryPress} style={styles.retryButton}>
          <Text style={styles.retryButtonText}>Retry startup</Text>
        </Pressable>
      </View>
    );
  }

  /* ─── Phase: ready ─── */

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.scrollContent}>
      {/* Header */}
      <Text style={styles.title}>CampusNav</Text>
      <Text style={styles.subtitle}>Visitor runtime — no sign-in needed</Text>
      <Text style={styles.statusLabel}>Graph: {graph!.graph.buildings.length} buildings</Text>

      {/* Destination Picker */}
      <View style={styles.section}>
        <DestinationPicker
          graph={graph!}
          selection={selection}
          onNodeSelect={onNodeSelect}
        />
      </View>

      {/* Route Preview (when ready) */}
      {sessionState && sessionState.phase === 'ready' && (
        <View style={styles.section}>
          <RoutePreview
            directions={sessionState.directions}
            accessibleMode={accessibleMode}
          />
        </View>
      )}

      {/* Session phase / route status */}
      {sessionState && (
        <View style={styles.sessionStatus}>
          <Text style={styles.statusLabel}>Route: {sessionState.phase}</Text>
          {sessionState.phase === 'no-route' && (
            <Text style={styles.statusMessage}>No path found between selected locations.</Text>
          )}
          {sessionState.phase === 'error' && (
            <Text style={styles.errorReason}>{sessionState.errorMessage}</Text>
          )}
        </View>
      )}

      {/* Map Viewport with floor switcher */}
      <View style={styles.section}>
        <MapViewportFloor
          floorTargets={floorTargets}
          activeFloorTarget={activeFloorTarget}
          routePath={routePath}
          onFloorChange={setActiveFloorTarget}
          showRouteOverlay={sessionState?.phase === 'ready'}
          showFloorSelector={floorTargets.length > 1}
          onTransformChange={onTransformChange}
        />
      </View>

      {/* Accessible mode toggle */}
      <View style={styles.toggleRow}>
        <Text style={styles.toggleLabel}>Accessible mode</Text>
        <Pressable
          style={[styles.toggleButton, accessibleMode && styles.toggleButtonActive]}
          onPress={toggleAccessibleMode}
        >
          <Text style={[styles.toggleButtonText, accessibleMode && styles.toggleButtonTextActive]}>
            {accessibleMode ? 'ON' : 'OFF'}
          </Text>
        </Pressable>
      </View>

      {/* Telemetry */}
      <Text style={styles.telemetryText}>
        viewport scale={formatMetric(transformState.scale)} rotation={formatMetric(transformState.rotationDeg)}°
        tx={formatMetric(transformState.translation.x)} ty={formatMetric(transformState.translation.y)}
      </Text>
    </ScrollView>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#020617',
  },
  scrollContent: {
    paddingHorizontal: 16,
    paddingVertical: 16,
    gap: 12,
  },
  title: {
    color: '#f8fafc',
    fontSize: 28,
    fontWeight: '700',
  },
  subtitle: {
    color: '#cbd5e1',
    fontSize: 14,
    marginBottom: 4,
  },
  statusLabel: {
    color: '#e2e8f0',
    fontSize: 15,
    fontWeight: '600',
  },
  statusMessage: {
    color: '#94a3b8',
    fontSize: 13,
    marginBottom: 4,
  },
  loadingRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  loadingText: {
    color: '#38bdf8',
    fontSize: 13,
  },
  section: {
    minHeight: 120,
    backgroundColor: '#0a0f1e',
    borderRadius: 12,
    overflow: 'hidden',
  },
  sessionStatus: {
    gap: 2,
  },
  errorReason: {
    color: '#fda4af',
    fontSize: 12,
  },
  retryButton: {
    marginTop: 6,
    backgroundColor: '#0f172a',
    borderColor: '#475569',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 14,
    paddingVertical: 8,
    alignSelf: 'flex-start',
  },
  retryButtonText: {
    color: '#f8fafc',
    fontSize: 13,
    fontWeight: '600',
  },
  toggleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 4,
  },
  toggleLabel: {
    color: '#cbd5e1',
    fontSize: 14,
    fontWeight: '500',
  },
  toggleButton: {
    backgroundColor: '#0f172a',
    borderColor: '#334155',
    borderWidth: 1,
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 8,
  },
  toggleButtonActive: {
    backgroundColor: '#0c2d4a',
    borderColor: '#38bdf8',
    borderWidth: 1.5,
  },
  toggleButtonText: {
    color: '#94a3b8',
    fontSize: 13,
    fontWeight: '600',
  },
  toggleButtonTextActive: {
    color: '#38bdf8',
  },
  telemetryText: {
    color: '#64748b',
    fontSize: 12,
    fontVariant: ['tabular-nums'],
    marginBottom: 8,
  },
});

