/**
 * Tests for MapViewportFloor component.
 */

import { describe, expect, it, vi } from 'vitest';
import { render, fireEvent, screen } from '@testing-library/react-native';
import { MapViewportFloor } from './MapViewportFloor';
import type { FloorPlanTarget } from '../../data/mapApiClient';
import type { RoutePathPoint } from '../route/RoutePathOverlay';

const TEST_FLOOR_TARGETS: FloorPlanTarget[] = [
